  "reviews {month}": "{month}出 review",
  "decision {month}": "{month}出结果",
  "Rebuttal for “{title}” due this month — open OpenRegret": "“{title}”的 rebuttal 这个月截止——打开 OpenRegret",
  "Draft with {name} — reply in ~{n} wk": "草稿在 {name} 手里——大约 {n} 周后回复",
  "“{title}” is approved — submit when a venue is open": "“{title}”已获批——等有投稿场所开放就提交",
