  "Pick a plan for the month, then Continue. Everything else is optional.": "选一个本月计划，然后继续。其他都是可选的。",
  "Start a project in the Projects box, or just Continue and see what the month brings.": "在“项目”框里开一个项目，或者直接继续，看看这个月会带来什么。",
  "Your advisor asked for something. Answer it (or don’t), then Continue.": "导师提了个要求。回应它（或者不回应），然后继续。",
  "A draft is approved. Submit it in Netscope → OpenRegret when a venue is open.": "有草稿通过了审阅。等哪个投稿场所开放，就在 Netscope → OpenRegret 里提交。",
  "Reviews are in. Write the rebuttal in OpenRegret this month.": "Review 来了。这个月在 OpenRegret 里写 rebuttal。",
